-- Instruction memory of the Basys 3 demo: 256 words, synchronous read (one BRAM).
-- The word at "addr" is on "data" one clock later; "data" is held while en = '0'.
-- The contents are generated by asm/build_rom.py.

entity ROM is
    Port (
    clk: in std_logic;
    en: in std_logic; -- read enable
    addr: in std_logic_vector(31 downto 0); -- byte address from the core
    data: out std_logic_vector(31 downto 0) -- instruction
     );
end ROM;

